class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int t=a%b;
            a=b;
            b=t;
        }
        return a;
    }
    public int commonFactors(int a,int b){
        int value=gcd(a,b),answer=0;
        for(int divisor=1;divisor*divisor<=value;divisor++)if(value%divisor==0)answer+=divisor*divisor==value?1:2;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun commonFactors(aValue:Int,bValue:Int):Int{
        var a=aValue;
        var b=bValue;
        while(b!=0){
            val t=a%b;
            a=b;
            b=t
        };
        var answer=0;
        var divisor=1;
        while(divisor*divisor<=a){
            if(a%divisor==0)answer+=if(divisor*divisor==a)1 else 2;
            divisor++
        };
        return answer
    }
}

